ALTER TABLE "sales" ADD COLUMN "discount_total" numeric(12,2) NOT NULL DEFAULT 0;
ALTER TABLE "sale_items" ADD COLUMN "original_unit_price" numeric(10,2) NOT NULL DEFAULT 0, ADD COLUMN "discount_amount" numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN "promotion_name" varchar(120);
UPDATE "sale_items" SET "original_unit_price" = "unit_price";
CREATE TABLE "promotions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "name" varchar(120) NOT NULL, "product_id" uuid, "discount_type" varchar(20) NOT NULL, "discount_value" numeric(10,2) NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "active" boolean DEFAULT true NOT NULL, "created_by" uuid, "created_at" timestamptz DEFAULT now() NOT NULL, CONSTRAINT "promotions_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE, CONSTRAINT "promotions_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "users"("id") ON DELETE SET NULL, CONSTRAINT "promotions_discount_type_check" CHECK ("discount_type" in ('percent', 'fixed')), CONSTRAINT "promotions_discount_value_positive" CHECK ("discount_value" > 0), CONSTRAINT "promotions_percent_max_check" CHECK ("discount_type" <> 'percent' or "discount_value" <= 100), CONSTRAINT "promotions_dates_check" CHECK ("ends_at" > "starts_at"));
CREATE INDEX "promotions_active_dates_idx" ON "promotions" ("active", "starts_at", "ends_at");
CREATE INDEX "promotions_product_idx" ON "promotions" ("product_id");
